\label{ex:CFKM}
An explicit example of an intermittent map to which our theory applies is the map $T:M\to M$, $M=[0,1]$, given by
\begin{equation}
    \label{eq:CFKM}
    Tx = \begin{cases} 
        x(1+3^{1/\alpha} x^{1/\alpha}), & x \in[0, \frac{1}{3})  , \\
        3x-1, & x\in[\frac{1}{3}, \frac{2}{3})  , \\
        1 - (1-x) (1 + 3^{1/\alpha} (1-x)^{1/\alpha}), & x\in[ \frac{2}{3},1],
  \end{cases}
\end{equation}
where $\alpha\in(1,2]$. There is a unique absolute continuous $T$-invariant probability measure $\mu_M$.
This example is taken from~\cite{CFKM20}; the symmetry around $x=\frac12$ is irrelevant but we require that the exponents $1+1/\alpha$ at the neutral fixed points coincide.

Let $a_n=n^{1/\alpha}$ for $\alpha\in(1,2)$ and
$a_n=(n\log n)^{1/2}$ for $\alpha=2$.
Given $v:M\to{\mathbb R}^d$, we define $v_n=\sum_{j=0}^{n-1}v\circ T^j$.

\begin{thm} \label{thm:CFKM}
Let $T:M\to M$ be the map~\eqref{eq:CFKM} with $\alpha\in(1,2]$.
Let $v:M\to{\mathbb R}$ be a H\"older observable with $\int_M v\,d\mu_M=0$ and satisfying $v(0),\,v(1)\neq0$ and $v(0)\neq v(1)$.  It is known (see for example~\cite{CFKM20}) that $a_n^{-1}v_n$ converges in distribution to a two-sided $\alpha$-stable law $X_\alpha$; we denote the density of $X_\alpha$ by $g$.

 Under an aperiodicity assumption that holds typically,
\[
\lim_{n\to\infty}a_n\int_M \zeta_1\,\zeta_2\circ T^n\,\xi\circ(v_n-qa_n)\,d\mu_M
=g(q)\int_M \zeta_1\,d\mu_M \int_M \zeta_2\,d\mu_M \int_{\mathbb R} \xi\,d\operatorname{Leb},
\]
for all $\zeta_1,\,\zeta_2\in C_c\big((0,1)\big)$, $\xi\in C_c({\mathbb R})$, $q\in{\mathbb R}$.
\end{thm}

The $\xi$ component encompasses the stable local limit theorem, whereas the test functions $\zeta_1$ and $\zeta_2$ represent mixing properties of $T$. Hence Theorem~\ref{thm:CFKM} is called a \emph{mixing local limit theorem (MLLT)}.

By the choice of $c$, in this range, $m\approx t$.
Choose $r\in(0,\alpha-1)$. Then
\begin{align*}
\sum_{La_t<  |m-t/{\bar{\tau}}|<ct} {\widetilde Q}_m(t) 
  & \ll \frac{t}{a_t^{d+1}}
\sum_{ m-t/{\bar{\tau}}> L a_t}
\frac{\tilde\ell(m{\bar{\tau}}-t)}{(m{\bar{\tau}}-t)^\alpha} \Big(1+\Big(\frac{m{\bar{\tau}}-t}{a_t}\Big)^r\Big) \\
  & \ll \frac{t}{a_t^{d+1+r}}
\sum_{ m-t/{\bar{\tau}}> L a_t}
\frac{\tilde\ell(m{\bar{\tau}}-t)}{(m{\bar{\tau}}-t)^{\alpha-r}} \\
&  \approx 
\frac{t}{a_t^{d+1+r}} \frac{\tilde\ell(a_t)}{(La_t)^{\alpha-1-r}}
\approx \frac{1}{a_t^d} \frac{1}{L^{\alpha-1-r}}\frac{t\tilde\ell(a_t)}{a_t^{\alpha}}
\end{align*}
by Karamata. 
The result follows since $a_t^\alpha\sim t\tilde\ell(a_t)$.

\label{prop:3}
\(
\lim_{t\to\infty}a_t^d\sum_{m\ge t^\gamma,\,m-t/{\bar{\tau}}\le -ct}{\widetilde Q}_m(t)=0
\)
for all $c>0$,

Write the range as $t^\gamma\le m\le c't$ where
$c'=1/{\bar{\tau}}-c$. (If $c'\le0$, then there is nothing to prove.)
Let $r,\,s>0$.
Since $t-m{\bar{\tau}}\gg t$,
\begin{align*}
\sum_{t^\gamma\le m\le c't} {\widetilde Q}_m(t)
\ll \sum_{t^\gamma\le m\le c't}\frac{m}{a_m^{d+1}}\,\frac{\tilde\ell(t)}{t^{\alpha-r}}
& \ll t^{-\alpha+r+s} \sum_{t^\gamma\le m\le c't}\frac{1}{m^{(d+1)/\alpha-s-1}}
\\ & \approx t^{-\alpha+r+s} 
\big\{(t^\gamma)^{2-(d+1)/\alpha+s}
+t^{2-(d+1)/\alpha+s}\big\}.
\end{align*}
Since $\alpha+1/\alpha>2$, we can shrink $r,\,s>0$ so that
\[
a_t^d\sum_{t^\gamma\le m\le c't} {\widetilde Q}_m(t)\ll t^{d/\alpha-\alpha+r+2s}(t^\gamma)^{2-(d+1)/\alpha+s}+o(1).
\]

If $d<\alpha^2$, then $\gamma=0$ and we see immediately that $a_t^d\sum_{1\le m\le c't} {\widetilde Q}_m(t)=o(1)$ for $r,\,s>0$ sufficiently small.

If $d\ge \alpha^2$, then the choice of $\gamma>\gamma_0$ ensures that
$d/\alpha-\alpha+\gamma(2-(d+1)/\alpha)<0$ and the result again follows.

Write $\Psi=X+{\widetilde Z}$ where
$X={\widetilde \omega} \tau$, 
${\widetilde \omega}|_{Y_i}\equiv {\widetilde \omega}_i$, ${\widetilde Z}=(Z,-{\bar{\tau}})$.
Since ${\widetilde Z}\in L^p$ with $p>\alpha$, it is easily seen that $\Psi$ is regularly varying if and only if $X$ is regularly varying, in which case they have the same index and spectral measure. Hence it suffices to verify the desired properties for $X$ instead of $\Psi$.

First, we show that $X$ is regularly varying with the given spectral measure $\sigma_{d+1}$. Fix $j\in\{1,\dots,k\}$ and let $E\subset{\mathbb S}^d$ be a Borel set containing ${\widehat \omega}_j$ such that ${\widehat \omega}_i\not\in E$ for $i\neq j$.
Since the vectors ${\widehat \omega}_i$ are distinct, 
it suffices to show that
\begin{equation} \label{eq:X1}
        \lim_{t \to \infty}
        \frac{\mu(|X| > \lambda t, \ X / |X| \in E)}{\mu(|X| > t)}
        = \lambda^{-\alpha}N^{-1} c_j|{\widetilde \omega}_j|^\alpha.
\end{equation} 
Now, $X/|X|=\sum_i 1_{Y_i}{\widehat \omega}_i$ and hence
$X(y)/|X(y)|\in E$ if and only if $y\in Y_j$.
It follows that
\begin{align*}
\mu(|X| > \lambda t, \ X / |X| \in E) & =
\mu(y\in Y_j:|X(y)| > \lambda t)
 =\mu(y\in Y_j:|{\widetilde \omega}_j|\tau(y) > \lambda t)
\\ &\sim c_j \ell(\lambda t/|{\widetilde \omega}_j|)|{\widetilde \omega}_j|^\alpha \lambda^{-\alpha}t^{-\alpha}
\sim c_j \ell(t)|{\widetilde \omega}_j|^\alpha \lambda^{-\alpha}t^{-\alpha}
\end{align*}
as $t\to\infty$ for all $\lambda>0$.
Similarly,
\begin{align*}
\mu(|X| > t) & = \sum_i \mu(y\in Y_i: |X(y)|>t)
 = \sum_i \mu(y\in Y_i: |{\widetilde \omega}_i|\tau(y)>t)
 \\ &\sim \sum_i c_i\ell(t/|{\widetilde \omega}_i|)|{\widetilde \omega}_i|^\alpha t^{-\alpha}
 \sim \sum_i c_i\ell(t)|{\widetilde \omega}_i|^\alpha t^{-\alpha}
=N\ell(t) t^{-\alpha},
\end{align*}
and~\eqref{eq:X1} follows.

It remains to verify the statement about nondegeneracy.
We have seen that $\sigma_{d+1}=\sum_{i=1}^k e_i\delta_{{\widehat \omega}_i}$ where $e_i>0$.
Hence $\int_{{\mathbb S}^d}|b\cdot x|^\alpha\,d\sigma_{d+1}(x)=
\sum_{i=1}^k e_i |b\cdot{\widehat \omega}_i|^\alpha$. Since $e_i>0$,
degeneracy reduces to the condition that 
$b\cdot{\widehat \omega}_1=\cdots=b\cdot{\widehat \omega}_k=0$ for some $b\in{\mathbb S}^d$.
Equivalently, ${\widehat \omega}_1,\dots,{\widehat \omega}_k$ do not span ${\mathbb R}^{d+1}$.

\label{prop:relax}
Suppose that $d\ge\alpha^2$ and define $\gamma_0$ as in \ref{itm:N3}.
Suppose that $Z\in L^2\cap L^p$ for some 
\[
p> \frac{2d}{\alpha}\,\frac{d+1-2\alpha}{d+\alpha^2-4\alpha+2}\,.\;
\footnote{Note that $\frac{d+1-2\alpha}{d+\alpha^2-4\alpha+2}<1$, so it suffices that $p>\frac{2d}{\alpha}$.}
\]
Assume that for some $\gamma\in(\gamma_0,1)$, there exists $c>0$ such that
\begin{equation} \label{eq:relax}
\mu\big(\min_{1\le m\le t^\gamma}|(\omega\tau)_m|/\tau_m < c\big) =o(a_t^{-d})
\quad\text{as $t\to\infty$}.
\end{equation}
Then \ref{itm:N3} holds.

\label{lem:NUEflow}
\begin{itemize}
\item[(a)] $\Psi$ satisfies~\eqref{eq:Psireg} with $\theta_1=\theta^\eta$ instead of $\theta$;
\item[(b)]  $H|_A$ is uniformly continuous for all 
subsets $A=A_0\times I\subset Y^\tau$ where $A_0\subset Y$ is measurable and
$I\subset [0,\inf_{A_0}\tau]$ is an interval.
\end{itemize}

\label{lem:Port}
Let $\lambda_t^\gamma$, $t>0$, $\gamma\in\Gamma$, and $\lambda$ be Radon measures on ${\mathbb R}^m$. 
Let ${\mathcal E}_\lambda$ denote the collection of bounded measurable subsets of ${\mathbb R}^m$ with $\lambda(\partial E)=0$.
Then the following are equivalent:
\begin{itemize}
\item[(a)] $\int_{{\mathbb R}^m} g\,d\lambda_t^\gamma\to \int_{{\mathbb R}^m}g\,d\lambda$
uniformly in $\gamma$ for each $g\in C_c({\mathbb R}^m)$.
\item[(b)] $\lim_{t\to\infty}\lambda_t^\gamma(E)= \lambda(E)$ uniformly in $\gamma$
for each $E\in{\mathcal E}_\lambda$.
\end{itemize}

\label{thm:LLT}
Let $\zeta_1\in {\mathcal F}_\theta$, $\zeta_2\in L^1$.  
Let $K\subset{\mathbb R}^{m_1}$ be bounded with $|\partial K|=0$, and let $L>0$.
Then
\begin{align*}
\lim_{n\to\infty}
\sup_{\genfrac{}{}{0pt}{}{z\in{\mathbb R}^m}{|z|\le L}}
\Big| a_n^m\, \int_Y\zeta_1\;\zeta_2\circ F^n\; & 1_{\{u_n\in z_1a_n+K,\,{\hat v}^{(n)}=[z_2a_n]\}} \,d\mu

-g_{X_\alpha}(z)\int_Y\zeta_1\,d\mu\int_Y\zeta_2\,d\mu\Big|=0.
\end{align*}

\label{prop:R}
Let $\alpha'\in(0,\alpha)$.
There exist ${\epsilon},\,c,\,C>0$, $\delta_0\in(0,1)$, such that
\begin{itemize}
\item[(a)] $R(s)=\lambda(s)P(s)+Q(s)$, \hspace{1em}
(b) $\|P(s)-P(0)\|\le C|s|$,
\item[(c)] $\|Q(s)\|^n\le C\delta_0^n$, \hspace{4.5em}
(d) $|\lambda(s)|\le \exp\{-c|s|^\alpha \tilde\ell(1/|s|)\}$,
\end{itemize}
for $|s|\le {\epsilon}$, $n\ge1$, and
\begin{itemize}
\item[(e)] 
$|\lambda(a_n^{-1}s)|^n\le Ce^{-c|s|^{\alpha'}}$ for $|s|\le {\epsilon} a_n$
and $n$ sufficiently large,
\item[(f)] $\lim_{n\to\infty}\lambda(a_n^{-1}s)^n= {\mathbb E}(e^{is\cdot X_\alpha})$
for all $s\in{\mathbb R}^m$.
\end{itemize}

\label{prop:ap}
For any $M>{\epsilon}>0$,  there exist $C>0$, $\delta_0\in(0,1)$ such that
\[
\|R(s)^n\|\le C\delta_0^n
\quad\text{for ${\epsilon}\le |s|\le M$.}
\]

\label{prop:A}
Let $A\subset Y$ be measurable with $\mu(\partial A)=0$.
For any ${\epsilon}>0$, there exist $A_1,A_2\subset Y$ with $1_{A_1},\,1_{A_2}\in{\mathcal F}_\theta$ such that $A_1\subset A\subset A_2$ and $\mu(A_2)-\mu(A_1)<{\epsilon}$.

\label{cor:LLT}
Let $A,B\subset Y$ be measurable sets with $\mu(\partial A)=0$.
Let $K\subset{\mathbb R}^{m_1}$ be bounded with $|\partial K|=0$, and let $L>0$. Then
\begin{align*}
\lim_{n\to\infty} \sup_{\genfrac{}{}{0pt}{}{z\in{\mathbb R}^m}{|z|\le L}}
\Big|a_n^m\mu\big(y\in A\cap  F^{-n}B:\, u_n(y)\in z_1a_n + & K,\,
{\hat v}^{(n)}(y)=[z_2a_n]\big)
\\ & - g_{X_\alpha}(z)\mu(A)\mu(B)|K|\Big|=0.
\end{align*}

\label{cor:LLTvague}
Let $\zeta_1,\,\zeta_2:Y\to{\mathbb R}$
be bounded almost every continuous functions,
$\xi\in C_c({\mathbb R}^m)$, $L>0$. Then
\begin{align*}
\lim_{n\to\infty} \sup_{\genfrac{}{}{0pt}{}{z\in{\mathbb R}^m}{|z|\le L}}
a_n^m\int_Y \zeta_1\;\zeta_2\circ F^n &  \;\xi\circ(u_n-z_1a_n,{\hat v}^{(n)}]-[z_2a_n])\,d\mu
\\ & \qquad =g_{X_\alpha}(z)\int_Y \zeta_1\,d\mu
\int_Y \zeta_2\,d\mu
\int_{{\mathbb R}^m} \xi\,d\operatorname{Leb}.
\end{align*}

\label{thm:LLTtwo}
Let $(F,Y,\mu)$ be a mixing two-sided Gibbs-Markov map with one-sided quotient
${\bar{\pi}}:Y\to{\bar Y}$, and
let ${\mathcal A}$ denote the collection of measurable subsets $A\subset Y$ with $\mu(\partial A)=0$.

Assume that $\Psi=(u,v):Y\to{\mathbb R}^{m_1}\times{\mathbb Z}^{m_2}$ is aperiodic, nondegenerate, regularly varying with index $-\alpha$,  $\alpha\in(1,2]$.
Suppose further that $v$ is locally constant and that $u$ admits a decomposition of the form
\begin{equation} \label{eq:chi0}
u={\bar u}\circ\bar\pi+\chi\circ F-\chi,
\end{equation}
where ${\bar u}:{\bar Y}\to{\mathbb R}^{m_1}$ satisfies~\eqref{eq:Psireg0} and
$\chi|_A:A\to{\mathbb R}^{m_1}$ is uniformly continuous
for each $A\in{\mathcal A}$.

Then
\begin{align*}
\lim_{n\to\infty} \sup_{\genfrac{}{}{0pt}{}{z\in{\mathbb R}^m}{|z|\le L}}
\Big|a_n^m\mu\big(y\in A\cap  F^{-n}B:\, u_n(y) \in z_1a_n +K, &
\, {\hat v}^{(n)}(y)=[z_2a_n]   \big)
\\ & - g_{X_\alpha}(z)\mu(A)\mu(B)|K|\Big|=0,
\end{align*}
for all $A,B\in{\mathcal A}$,
$K\subset{\mathbb R}^{m_1}$ bounded with $|\partial K|=0$, and $L>0$.
